package com.nthexperience.desktop;

import android.app.*;
import android.content.*;
import android.content.pm.ActivityInfo;
import android.graphics.Bitmap;
import android.os.*;
import android.view.*;
import android.widget.*;
import java.io.*;
import java.util.concurrent.*;
import org.json.*;

/** Exercises native surfaces, real window continuity and profile isolation without cloud calls. */
public final class EightSmoke extends Instrumentation {
    private void choose(EightProfile profile)throws Exception{home=EightShellSwitch.choose(this,home,profile);root=home.getWindow().getDecorView();}
    MainActivity home;View root;DesktopStore store;
    @Override public void onCreate(Bundle args){super.onCreate(args);start();}
    @Override public void onStart(){Bundle result=new Bundle();try{
        store=new DesktopStore(getTargetContext());EightDefaults.initialize(store);
        store.prefs.edit().putString("eight_profile","8").putInt("startup_mode",2).putBoolean("welcome_on_start",false).putBoolean("reduce_motion",true).putBoolean("taskbar_apps",false).commit();
        getTargetContext().getSharedPreferences(StorageAccess.PREFS,0).edit().putBoolean("seen",true).commit();
        getTargetContext().getSharedPreferences(StartupExperience.SESSION,0).edit().putBoolean("seen",true).putBoolean("welcome_seen",true).putBoolean(StartupExperience.HOME_OFFERED,true).commit();
        home=(MainActivity)startActivitySync(new Intent(Intent.ACTION_MAIN).setComponent(new ComponentName(getTargetContext(),MainActivity.class)).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));root=home.getWindow().getDecorView();waitForIdleSync();
        check(getTargetContext().getPackageName().equals("com.nthexperience.desktop.eight"),"Independent Eight package");
        ui(()->{EightStartScreen start=find(root,EightStartScreen.class);check(start.isShown(),"First launch enters Start");check(start.profile==EightProfile.EIGHT,"Eight selected initially");check(start.getParent()!=description(root,"Desktop workspace"),"Start has a separate surface");check(description(root,"Task View")==null&&description(root,"Action Center")==null,"Ten taskbar controls removed");});shot("eight-start-portrait");
        ui(()->{home.open("@notes");EditText note=(EditText)description(root,"Notepad text");check(note!=null&&note.isShown(),"Desktop app opens from Start");note.setText("Eight continuity fixture");home.open("@start");check(find(root,EightStartScreen.class).isShown(),"Start covers desktop");home.open("@desktop");check(note.isShown()&&note.getText().toString().equals("Eight continuity fixture"),"Desktop tile preserves window and content");});shot("eight-desktop");
        ui(()->{home.open("@start");EightStartScreen start=find(root,EightStartScreen.class);View tile=description(start,"Nth Nota, Wide Start tile");check(tile!=null,"Seeded working Nota tile");tile.performLongClick();check(description(start,"Resize selected tile")!=null,"Hold reveals selection app bar");start.back();start.data.item("@nota").size="Medium";start.data.save();start.appearanceChanged();home.open("@settings");View profile=description(root,"Use Windows 8.1 shell");check(profile!=null&&profile.isShown(),"Shell selector discoverable");});choose(EightProfile.EIGHT_POINT_ONE);shot("eight-profile-81-desktop");ui(()->{check(!find(root,EightStartScreen.class).isShown(),"8.1 refresh lands on Desktop");navigationDefaults(true);check(EightDefaults.profile(store)==EightProfile.EIGHT_POINT_ONE,"8.1 selection saved");home.open("@desktop");check(description(root,"Start screen").isShown(),"8.1 has visible desktop Start button");home.open("@start");EightStartScreen start=find(root,EightStartScreen.class);check(start.profile==EightProfile.EIGHT_POINT_ONE,"8.1 renderer selected");check(start.data.item("@nota").size.equals("Wide"),"8.1 layout remains independent");start.data.item("@nota").size="Large";start.data.save();});shot("eight-one-start");
        ui(()->{home.open("eight-desktop:taskbar");EightTaskbarProperties properties=find(root,EightTaskbarProperties.class);properties.tab="Navigation";properties.render();for(String title:new String[]{"Go to Desktop when Eight launches","Show desktop background on Start","8.1 Update mouse controls and taskbar apps"})check(((CheckBox)description(properties,title)).isChecked(),"Navigation shows enabled 8.1 default: "+title);});shot("eight-profile-81-defaults");
        ui(()->{home.open("@settings");((CheckBox)description(root,"Open Desktop when Eight launches")).performClick();});MainActivity unchanged=home;choose(EightProfile.EIGHT_POINT_ONE);check(home==unchanged&&!store.prefs.getBoolean("eight_boot_desktop",true),"Same-shell selection preserves customized options without refreshing");
        ActivityMonitor ordinaryMonitor=addMonitor(MainActivity.class.getName(),null,false);ui(()->home.recreate());Activity ordinaryRefresh=ordinaryMonitor.waitForActivityWithTimeout(15000);removeMonitor(ordinaryMonitor);check(ordinaryRefresh instanceof MainActivity,"Normal refresh completes");home=(MainActivity)ordinaryRefresh;root=home.getWindow().getDecorView();waitForIdleSync();check(!store.prefs.getBoolean("eight_boot_desktop",true),"Normal refresh does not reset customized navigation");
        choose(EightProfile.EIGHT);shot("eight-profile-8-restored");ui(()->{check(find(root,EightStartScreen.class).isShown(),"8.0 refresh returns to Start");navigationDefaults(false);home.open("@desktop");check(description(root,"Start corner").getAlpha()==0f,"Original Eight corner cue");home.open("@start");EightStartScreen start=find(root,EightStartScreen.class);check(start.data.item("@nota").size.equals("Medium"),"Original layout restored without conversion");home.open("eight-search:Apps");start.search.setText("Notepad");check(description(start,"Open Notepad")!=null,"Search resolves actual Nth tools");description(start,"Open Notepad").performClick();check(((EditText)description(root,"Notepad text")).getText().toString().equals("Eight continuity fixture"),"Search restores existing app");});
        ui(()->{home.open("@start");description(root,"Open Charms").performClick();EightCharms charms=find(root,EightCharms.class);check(charms.isShown(),"Charms opens from handle");check(description(charms,"Search charm")!=null&&description(charms,"Share charm")!=null&&description(charms,"Start charm")!=null&&description(charms,"Devices charm")!=null&&description(charms,"Settings charm")!=null,"All five charms");charms.performClick();check(!charms.isShown(),"Outside tap dismisses Charms");description(root,"Open Charms").performClick();description(charms,"Settings charm").performClick();check(description(charms,"Start")!=null,"Settings charm uses Start context");});shot("eight-settings-charm");
        ui(()->{EightCharms charms=find(root,EightCharms.class);description(charms,"Change PC settings").performClick();check(find(root,EightPCSettings.class).isShown(),"Settings charm opens PC settings");try{JSONObject snapshot=DesktopBackup.snapshot(store);DesktopBackup.Plan plan=DesktopBackup.parse(snapshot.toString());check(plan.values.containsKey(EightStartData.EIGHT)&&plan.values.containsKey(EightStartData.EIGHT_ONE),"Backup keeps both layouts");check(new EightStartData(store,EightProfile.EIGHT_POINT_ONE).item("@nota").size.equals("Large"),"Unsupported size retained only in 8.1 profile");boolean rejected=false;try{DesktopBackup.parse(new JSONObject(snapshot.toString()).put("format","nth-desktop-backup").toString());}catch(JSONException expected){rejected=true;}check(rejected,"Ten backup rejected before mutation");}catch(JSONException e){throw new RuntimeException(e);}});shot("eight-pc-settings");
        ui(()->{home.open("@start");home.setRequestedOrientation(ActivityInfo.SCREEN_ORIENTATION_LANDSCAPE);});awaitOrientation(android.content.res.Configuration.ORIENTATION_LANDSCAPE);shot("eight-start-landscape");
        ui(()->{home.open("@settings");check(find(root,EightPCSettings.class).isShown(),"PC settings works in landscape");});shot("eight-settings-landscape");
        ActivityMonitor monitor=addMonitor(MainActivity.class.getName(),null,false);ui(()->home.recreate());Activity restored=monitor.waitForActivityWithTimeout(15000);removeMonitor(monitor);check(restored instanceof MainActivity,"Activity recreated");home=(MainActivity)restored;root=home.getWindow().getDecorView();waitForIdleSync();
        ui(()->{check(find(root,EightPCSettings.class).isShown(),"Settings surface restored after recreation");home.onNewIntent(new Intent(Intent.ACTION_MAIN).addCategory(Intent.CATEGORY_HOME));check(find(root,EightStartScreen.class).isShown(),"Android Home enters Start");home.open("@desktop");check(((EditText)description(root,"Notepad text")).getText().toString().equals("Eight continuity fixture"),"Window content survives recreation and Home");home.open("@start");});
        ui(()->{home.open("@desktop");home.dispatchKeyEvent(new KeyEvent(0,0,KeyEvent.ACTION_DOWN,KeyEvent.KEYCODE_TAB,0,KeyEvent.META_CTRL_ON));check(!find(root,EightStartScreen.class).isShown(),"Ctrl+Tab in desktop content does not open Apps");home.dispatchKeyEvent(new KeyEvent(0,0,KeyEvent.ACTION_DOWN,KeyEvent.KEYCODE_ESCAPE,0,KeyEvent.META_CTRL_ON|KeyEvent.META_SHIFT_ON));check(find(root,TaskManagerPanel.class).isShown(),"Ctrl+Shift+Escape opens Task Manager");home.open("@start");home.dispatchKeyEvent(new KeyEvent(KeyEvent.ACTION_DOWN,KeyEvent.KEYCODE_META_LEFT));home.dispatchKeyEvent(new KeyEvent(0,0,KeyEvent.ACTION_DOWN,KeyEvent.KEYCODE_W,0,KeyEvent.META_META_ON));home.dispatchKeyEvent(new KeyEvent(KeyEvent.ACTION_UP,KeyEvent.KEYCODE_META_LEFT));EightStartScreen start=find(root,EightStartScreen.class);check(start.isShown()&&start.surface==EightStartScreen.Surface.SEARCH&&start.scope.equals("Settings"),"Windows+W searches Settings without a spurious Start toggle");});
        result.putString("stream","PASS: Eight identity; Start/Desktop continuity; separate 8/8.1 layouts; recorded Navigation defaults, one refresh per change, no refresh/reset for same-shell taps; selection; search; five Charms; contextual Settings; backup isolation; portrait/landscape; recreation and Home\n");finish(Activity.RESULT_OK,result);
    }catch(Throwable failure){try{shot("eight-failure");}catch(Exception ignored){}result.putString("stream","FAIL: "+android.util.Log.getStackTraceString(failure));finish(Activity.RESULT_CANCELED,result);}}
    private void navigationDefaults(boolean expected){for(String key:new String[]{"eight_boot_desktop","eight_start_wallpaper","eight_81_update"})check(store.prefs.getBoolean(key,!expected)==expected,"Profile navigation default: "+key);}
    private void awaitOrientation(int orientation)throws Exception{long until=SystemClock.uptimeMillis()+10000;while(home.getResources().getConfiguration().orientation!=orientation&&SystemClock.uptimeMillis()<until){SystemClock.sleep(100);waitForIdleSync();}check(home.getResources().getConfiguration().orientation==orientation,"Rotation delivered");waitForIdleSync();SystemClock.sleep(300);}
    private void check(boolean value,String message){if(!value)throw new AssertionError(message);}
    private void ui(Runnable action)throws Exception{FutureTask<Void> task=new FutureTask<>(action,null);home.runOnUiThread(task);task.get(15,TimeUnit.SECONDS);waitForIdleSync();}
    private void shot(String name)throws Exception{
        waitForIdleSync();SystemClock.sleep(200);Bitmap bitmap=getUiAutomation().takeScreenshot();String source="device compositor";
        if(bitmap==null||blank(bitmap)){
            if(bitmap!=null)bitmap.recycle();
            bitmap=Bitmap.createBitmap(Math.max(1,root.getWidth()),Math.max(1,root.getHeight()),Bitmap.Config.ARGB_8888);
            Bitmap target=bitmap;ui(()->root.draw(new android.graphics.Canvas(target)));source="native View render (compositor capture was blank)";name+="-view";
        }
        check(!blank(bitmap),"Native visual evidence contains rendered content");
        try(OutputStream output=new FileOutputStream(new File(getTargetContext().getFilesDir(),name+".png"))){bitmap.compress(Bitmap.CompressFormat.PNG,100,output);}finally{bitmap.recycle();}
        try(Writer output=new FileWriter(new File(getTargetContext().getFilesDir(),"eight-capture.txt"),true)){output.write(name+": "+source+"\n");}
    }
    private boolean blank(Bitmap image){for(int y=0;y<image.getHeight();y+=24)for(int x=0;x<image.getWidth();x+=24)if((image.getPixel(x,y)&0xffffff)!=0)return false;return true;}

    static <T extends View>T find(View view,Class<T> type){if(type.isInstance(view))return type.cast(view);if(view instanceof ViewGroup)for(int i=0;i<((ViewGroup)view).getChildCount();i++){T result=find(((ViewGroup)view).getChildAt(i),type);if(result!=null)return result;}return null;}
    static View description(View view,String value){if(value.contentEquals(view.getContentDescription()==null?"":view.getContentDescription()))return view;if(view instanceof ViewGroup)for(int i=0;i<((ViewGroup)view).getChildCount();i++){View result=description(((ViewGroup)view).getChildAt(i),value);if(result!=null)return result;}return null;}
}
